{"file_path":"src/parse.js","content":"/**
 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidatesDeclared = false
  const candidates = []
  const candidatesSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed[0] === '#') continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesDeclared) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 2) {
        fail('expected candidates <name>...', lineNo)
      }
      for (let j = 1; j < tokens.length; j++) {
        const name = tokens[j]
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNo)
        }
        if (candidatesSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNo)
        }
        candidatesSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (word === 'ballot') {
      if (!candidatesDeclared) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNo)
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        fail('count must be a positive integer', lineNo)
      }
      const count = BigInt(countToken)
      const seen = new Set()
      const names = []
      for (let j = 2; j < tokens.length; j++) {
        const name = tokens[j]
        if (!candidatesSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`unknown directive ${word}`, lineNo)
    }
  }

  if (!candidatesDeclared) {
    fail('no candidates', null)
  }

  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/**
 * The instant-runoff counting logic.
 */

export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = [] // { votes: Map<name,BigInt>, exhausted: BigInt, eliminated: string|null }
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      let target = null
      for (const name of ballot.names) {
        if (continuing.has(name)) {
          target = name
          break
        }
      }
      if (target === null) {
        exhausted += ballot.count
      } else {
        votes.set(target, votes.get(target) + ballot.count)
      }
    }

    let activeTotal = 0n
    for (const c of continuing) activeTotal += votes.get(c)

    rounds.push({ votes, exhausted, eliminated: null })

    if (activeTotal === 0n) {
      winner = null
      break
    }

    let majorityWinner = null
    for (const c of continuing) {
      if (votes.get(c) * 2n > activeTotal) {
        majorityWinner = c
        break
      }
    }
    if (majorityWinner !== null) {
      winner = majorityWinner
      break
    }

    // Determine the candidate(s) with fewest votes this round.
    let fewest = null
    for (const c of continuing) {
      const v = votes.get(c)
      if (fewest === null || v < fewest) fewest = v
    }
    let survivors = [...continuing].filter((c) => votes.get(c) === fewest)

    if (survivors.length > 1) {
      for (let r = 0; r < rounds.length && survivors.length > 1; r++) {
        const roundVotes = rounds[r].votes
        const values = survivors.map((c) => roundVotes.get(c))
        const allEqual = values.every((v) => v === values[0])
        if (!allEqual) {
          let min = values[0]
          for (const v of values) if (v < min) min = v
          survivors = survivors.filter((c) => roundVotes.get(c) === min)
        }
      }
    }

    let eliminated
    if (survivors.length === 1) {
      eliminated = survivors[0]
    } else {
      eliminated = survivors.reduce((a, b) => (a > b ? a : b))
    }

    rounds[rounds.length - 1].eliminated = eliminated
    continuing = new Set([...continuing].filter((c) => c !== eliminated))
  }

  return { rounds, winner }
}
"}

